const string folder="Assets/ChibiSurvivor/Bandit/SimpleBandit";var prefab=UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(folder+"/SimpleBandit.prefab");var instance=UnityEngine.Object.Instantiate(prefab);instance.hideFlags=HideFlags.HideAndDontSave;instance.transform.position=new Vector3(0,-1000,0);
try{var animator=instance.GetComponentInChildren<Animator>();animator.Rebind();animator.Update(0);var smrs=instance.GetComponentsInChildren<SkinnedMeshRenderer>(true);if(smrs.Length!=2)throw new System.Exception("Renderer count");var body=smrs.Single(r=>r.name=="Bandit_Body");if(body.sharedMaterials.Length!=1||body.sharedMaterials[0].GetTexture("_BaseMap")==null||body.sharedMesh.uv.Length!=body.sharedMesh.vertexCount)throw new System.Exception("Body atlas");
var bones=instance.GetComponentsInChildren<Transform>(true);var r=bones.Single(t=>t.name=="HandSocket.R");var l=bones.Single(t=>t.name=="HandSocket.L");var records=new System.Collections.Generic.List<object>();
foreach(var state in new[]{"Locomotion","SwordWalk","SwordSlash"}){int layer=animator.GetLayerIndex("SwordHold");animator.SetLayerWeight(layer,state=="Locomotion"?1:0);animator.SetFloat("Speed",state=="Locomotion"?2:0);animator.Play("Base Layer."+state,0,0);animator.Update(0);float grip=0;var baked=new Mesh();try{for(int i=0;i<100;i++){animator.Update(.012f);grip=Mathf.Max(grip,Vector3.Distance(l.position,r.position-r.up*.15f));body.BakeMesh(baked);if(baked.vertices.Any(v=>!float.IsFinite(v.x)||!float.IsFinite(v.y)||!float.IsFinite(v.z)))throw new System.Exception("Invalid deformation");}if(grip>.008)throw new System.Exception("Grip "+state+" "+grip);records.Add(new{state,maxGripError=grip});}finally{UnityEngine.Object.DestroyImmediate(baked);}}
var result=new{passed=true,bodyRenderers=1,bodyMaterials=1,weaponSeparate=true,states=records,existingBanditsReplaced=false};System.IO.File.WriteAllText("D:/Demo/ArtWork/SimpleBandit/UnityCheck.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return result;
}finally{UnityEngine.Object.DestroyImmediate(instance);}
